use xiom.io;
enum Level {
  L0; L1; L2; L3; L4; L5; L6; L7; L8;
}

type Achievement {
  level: Level;
  name: Str;
  lessons: Int;
  highlight: Str;
}

fn build_achievements() -> Vec[Achievement] {
  let mut ach: Vec[Achievement] = Vec[Achievement].new();
  ach.push(Achievement{ level: Level.L0, name: "Foundations", lessons: 40, highlight: "Hello World & Variables" });
  ach.push(Achievement{ level: Level.L1, name: "Control Flow", lessons: 40, highlight: "Conditionals" });
  ach.push(Achievement{ level: Level.L2, name: "Iteration & Functions", lessons: 40, highlight: "Loops & Functions" });
  ach.push(Achievement{ level: Level.L3, name: "Advanced Types", lessons: 40, highlight: "Option, Result, Error Handling" });
  ach.push(Achievement{ level: Level.L4, name: "Data Modeling", lessons: 40, highlight: "Structs, Enums, Contracts" });
  ach.push(Achievement{ level: Level.L5, name: "Memory Management", lessons: 40, highlight: "Ownership & Borrowing" });
  ach.push(Achievement{ level: Level.L6, name: "Collections & Generics", lessons: 40, highlight: "Vec, Map, Generics" });
  ach.push(Achievement{ level: Level.L7, name: "Mastery", lessons: 40, highlight: "Modules & Capstone Suite" });
  ach.push(Achievement{ level: Level.L8, name: "Ecosystem", lessons: 20, highlight: "Games, Tools & Applications" });
  ach
}

fn list_skills_mastered() -> Vec[Str] {
  let mut skills: Vec[Str] = Vec[Str].new();
  skills.push("Variables & Types");
  skills.push("Conditionals (if/else)");
  skills.push("Loops (while/for)");
  skills.push("Functions & Parameters");
  skills.push("Structs (Custom Types)");
  skills.push("Enums (Tagged Unions)");
  skills.push("Pattern Matching (match)");
  skills.push("Contracts (requires/ensures)");
  skills.push("Ownership & Borrowing");
  skills.push("Vec & Map Collections");
  skills.push("Generics");
  skills.push("Modules & Code Organization");
  skills.push("Game Loop Architecture");
  skills.push("Data Analysis");
  skills
}

fn count_total_lessons(ach: &Vec[Achievement]) -> Int {
  let mut total = 0;
  let mut i = 0;
  while i < ach.len() {
    total = total + ach.get(i).unwrap().lessons;
    i = i + 1;
  };
  total
}

fn print_diploma(name: Str) {
  let achievements = build_achievements();
  let skills = list_skills_mastered();
  let total = count_total_lessons(&achievements);

  io.println("XIOM PROGRAMMING DIPLOMA");
  io.println(name.to_str());
  io.println(total.to_str());
  io.println("9 Levels Completed");

  io.println("SKILLS MASTERED:");
  let mut i = 0;
  while i < skills.len() {
    io.println(skills.get(i).unwrap().to_str());
    i = i + 1;
  };

  io.println("LEVELS COMPLETED:");
  let mut j = 0;
  while j < achievements.len() {
    let a = achievements.get(j).unwrap();
    io.println(a.name.to_str());
    io.println(a.lessons.to_str());
    io.println(a.highlight.to_str());
    j = j + 1;
  };

  io.println("This isn't the end. It's the beginning.");
  io.println("You are a programmer. Welcome to the club.");
  io.println("Go build something amazing.");

  let mut k = 0;
  while k < skills.len() {
    io.println(skills.get(k).unwrap().to_str());
    k = k + 1;
  };
}

fn main() -> Int {
  print_diploma("XIOM Graduate");
  return 0;
}
